flags.typeql:
match
$me isa me, has screen_name "neo4j", has betweenness $mb;
similar_to ($me, $user);
$user isa user, has betweenness $ub;
let $diff = abs($ub - $mb);
sort $diff asc;
limit 5;
fetch {
  "screen_name": $user.screen_name,
  "betweenness": $ub
};

match
$u isa user, has followers $f;
reduce $max_f = max($f);
match
$u2 isa user, has followers $f2;
$f2 == $max_f;
$t isa tweet, has favorites $fav;
mentions (source_tweet: $t, mentioned_user: $u2);
sort $fav desc;
limit 5;
fetch {
  "tweet": $t.text,
  "favorites": $t.favorites
};

match
$me isa me, has screen_name "neo4j";
similar_to ($me, $user);
$user has betweenness $ub, has following $uf;
$me has betweenness $mb, has following $mf;
let $similarity_score = abs($ub - $mb) + abs($uf - $mf);
sort $similarity_score asc;
limit 5;
fetch {
  "screen_name": $user.screen_name,
  "user_betweenness": $ub,
  "user_following": $uf,
  "me_betweenness": $mb,
  "me_following": $mf,
  "similarity_score": $similarity_score
};

match
$tweet isa tweet;
$rel isa $t;
{
  $t label mentions;
  $rel links (source_tweet: $tweet);
} or {
  $t label retweets;
  $rel links (retweeting_tweet: $tweet);
} or {
  $t label reply_to;
  $rel links (replying_tweet: $tweet);
};
reduce $count = count groupby $tweet;
sort $count desc;
limit 5;
fetch {
  "tweet_id": $tweet.id_str,
  "tweet_text": $tweet.text,
  "total_interactions": $count
};

with fun max_betweenness() -> double:
  match $u isa user, has betweenness $b;
  return max($b);
match
  $u isa user, has betweenness $b;
  let $max_b = max_betweenness();
  $b == $max_b;
  mentions (source_tweet: $t, mentioned_user: $u);
  $t has created_at $ca;
sort $ca asc;
limit 3;
fetch { "tweet_id": $t.tweet_id, "text": $t.text, "created_at": $t.created_at };

match
$t isa tweet, has favorites $f;
$l isa link;
contains (containing_tweet: $t, contained_link: $l);
sort $f desc;
limit 3;
fetch {
  "url": $l.link_url
};
